// === Tab: mySketch ===
let images = [];
let imgPositions = [];
let numImages = 5;
let targetHeight = 200;  // גובה קבוע לתמונות
let zIndexOrder = [];  // סדר הופעת התמונות בקדמת המסך
let speedFactors = [];  // קצב התגובה לתזוזת העכבר עבור כל תמונה
let minDistance = 200; // מרחק מינימלי בין התמונות
let containerWidth = 1000; // רוחב הקונטיינר
let containerHeight = 600; // גובה הקונטיינר
let containerX; // מיקום הקונטיינר
let containerY; // מיקום הקונטיינר

function preload() {
  // טוען את התמונות
  images[0] = loadImage('https://openprocessing.org/sketch/2374582/files/דשבשב.png');
  images[1] = loadImage('https://openprocessing.org/sketch/2374582/files/צילום מסך 2024-09-03 ב-14.07.01.png');
  images[2] = loadImage('https://openprocessing.org/sketch/2374582/files/צילום מסך 2024-09-04 ב-16.52.21.png');
  images[3] = loadImage('https://openprocessing.org/sketch/2374582/files/צילום מסך 2024-09-24 ב-14.20.05.png');
  images[4] = loadImage('https://openprocessing.org/sketch/2374582/files/צילום מסך 2024-09-23 ב-11.07.18.png');
}

function setup() {
  createCanvas(windowWidth, windowHeight);
  imageMode(CENTER);

  // קביעת מיקום הקונטיינר במרכז המסך
  containerX = (width - containerWidth) / 2;
  containerY = (height - containerHeight) / 2;

  // מיקומים התחלתיים לתמונות - פרוסות במרחב לא אחיד
  imgPositions = [
    { x: containerX + 100, y: containerY + 300 }, // דשבשב.png
    { x: containerX + 400, y: containerY + 300 }, // צילום מסך 2024-09-03 ב-14.07.01.png
    { x: containerX + 700, y: containerY + 300 }, // צילום מסך 2024-09-04 ב-16.52.21.png
    { x: containerX + 300, y: containerY + 500 }, // צילום מסך 2024-09-24 ב-14.20.05.png
    { x: containerX + 600, y: containerY + 500 }, // צילום מסך 2024-09-23 ב-11.07.18.png
  ];

  // קביעת קצב התגובה לכל תמונה (כדי שיתנהגו בצורה שונה)
  speedFactors = [0.05, 0.1, 0.07, 0.03, 0.08];

  // תחילה, מגדיר את סדר ה-z כך שהתמונה הראשונה תהיה בקדמת המסך
  zIndexOrder = [0, 1, 2, 3, 4];
}

function draw() {
  background(20);  // רקע כהה

  // עדכון מיקום התמונות בהתאם לעכבר
  updateImagePositions();

  // בדיקה מי התמונה הקרובה ביותר לעכבר
  let closestIndex = getClosestImageIndex();

  // סדר חדש לתמונות: התמונה הקרובה ביותר תהיה האחרונה להופיע (בקדמת המסך)
  let orderedIndices = zIndexOrder.slice();
  orderedIndices.splice(orderedIndices.indexOf(closestIndex), 1);
  orderedIndices.push(closestIndex);

  // הצגת התמונות לפי הסדר שנקבע (הקרובה לעכבר למעלה)
  for (let i of orderedIndices) {
    let img = images[i];
    let pos = imgPositions[i];

    // שמירת יחס רוחב-גובה
    let aspectRatio = img.width / img.height;
    let displayHeight = targetHeight;
    let displayWidth = displayHeight * aspectRatio;

    // הצגת התמונה (ללא blend mode)
    blendMode(BLEND);
    image(img, pos.x, pos.y, displayWidth, displayHeight);

    // צייר קו מחבר בין התמונה לתמונה הבאה (מקווקו)
    stroke(255, 200); // צבע הקו
    strokeWeight(0.5); // קו דק מאוד
    drawingContext.setLineDash([3, 3]); // קו מקווקו
    if (i < orderedIndices.length - 1) {
      let nextPos = imgPositions[orderedIndices[i + 1]];
      line(pos.x, pos.y, nextPos.x, nextPos.y);
    }

    // טקסט המיקום של התמונה (15 פיקסלים מתחת לתמונה)
    noStroke();
    fill(255);
    textSize(12);
    textFont('monospace'); // הגדרת גופן כמקודד

    // קביעת מצב ה-blend mode עבור הטקסט
    blendMode(DIFFERENCE);
    text(`(${int(pos.x)}, ${int(pos.y)})`, pos.x + displayWidth / 2 + 10, pos.y + targetHeight / 2 + 15); // טקסט 15 פיקסלים מתחת וימין לתמונה
  }

  // החזרת ה-blend mode למצב הרגיל
  blendMode(BLEND);
}

function getClosestImageIndex() {
  // מוצא את התמונה הקרובה ביותר לעכבר
  let closestDist = Infinity;
  var closestIndex = -1;

  for (let i = 0; i < imgPositions.length; i++) {
    let d = dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), imgPositions[i].x, imgPositions[i].y);
    if (d < closestDist) {
      closestDist = d;
      closestIndex = i;
    }
  }

  return closestIndex;
}

function updateImagePositions() {
  for (let i = 0; i < imgPositions.length; i++) {
    var pos = imgPositions[i];
    let targetX, targetY;

    // קביעת התנהגות מעקב שונה לכל תמונה
    if (i % 2 === 0) {
      // תמונות שעוקבות אחרי העכבר
      targetX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) + random(-15, 15); // תזוזה קטנה סביב העכבר
      targetY = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) + random(-15, 15);
    } else {
      // תמונות שמנוגדות לעכבר
      targetX = width - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) + random(-15, 15);
      targetY = height - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) + random(-15, 15);
    }

    // לוודא שהמיקומים נשמרים בתוך גבולות הקונטיינר הדמיוני
    targetX = constrain(targetX, containerX + targetHeight / 2, containerX + containerWidth - targetHeight / 2);
    targetY = constrain(targetY, containerY + targetHeight / 2, containerY + containerHeight - targetHeight / 2);

    // עדכון מיקום התמונות בצורה חלקה
    pos.x = lerp(pos.x, targetX, speedFactors[i]);
    pos.y = lerp(pos.y, targetY, speedFactors[i]);

    // לוודא שהתמונות לא קרובות מדי אחת לשנייה
    for (let j = 0; j < imgPositions.length; j++) {
      if (i !== j) {
        let otherPos = imgPositions[j];
        var d = dist(pos.x, pos.y, otherPos.x, otherPos.y);
        if (d < minDistance) {
          let angle = atan2(pos.y - otherPos.y, pos.x - otherPos.x);
          pos.x += cos(angle) * (minDistance - d); // דחוף את התמונה במקביל לזווית
          pos.y += sin(angle) * (minDistance - d);
        }
      }
    }
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  // קביעת מיקום הקונטיינר במרכז המסך
  containerX = (width - containerWidth) / 2;
  containerY = (height - containerHeight) / 2;

  // התאמת המיקומים החדשים לגודל המסך
  imgPositions[0] = { x: containerX + 100, y: containerY + 300 };
  imgPositions[1] = { x: containerX + 400, y: containerY + 300 };
  imgPositions[2] = { x: containerX + 700, y: containerY + 300 };
  imgPositions[3] = { x: containerX + 300, y: containerY + 500 };
  imgPositions[4] = { x: containerX + 600, y: containerY + 500 };
}


